uid_t target_ruid = 1000;
uid_t target_euid = 1000;

// Set both Real and Effective UIDs
if (setreuid(target_ruid, target_euid) == -1) {
    // Requires appropriate privileges (often root)
    // Check EPERM, EAGAIN, EINVAL
}

// Change only Effective UID (e.g., restoring previous privilege)
// RUID remains unchanged (-1)
uid_t new_euid = 1001;
if (setreuid(-1, new_euid) == -1) {
    /* error handling */
}

// Preserve EUID, change RUID (restricted to privileged processes)
uid_t new_ruid = 1002;
setreuid(new_ruid, -1);
